    /// <summary>
    /// A Json converter for type <see cref="Country"/>
    /// </summary>
    /// <exception cref="NotImplementedException"></exception>
    public class CountryJsonConverter : JsonConverter<Country>
    {
        /// <summary>
        /// Returns a  from the Json object
        /// </summary>
        /// <param name="reader"></param>
        /// <param name="typeToConvert"></param>
        /// <param name="options"></param>
        /// <returns></returns>
        public override Country Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            string? rawValue = reader.GetString();

            Country? result = rawValue == null
                ? null
                : CountryValueConverter.FromStringOrDefault(rawValue);

            if (result != null)
                return result.Value;

            throw new JsonException();
        }

        /// <summary>
        /// Writes the Country to the json writer
        /// </summary>
        /// <param name="writer"></param>
        /// <param name="country"></param>
        /// <param name="options"></param>
        public override void Write(Utf8JsonWriter writer, Country country, JsonSerializerOptions options)
        {
            writer.WriteStringValue(country.ToString());
        }
    }

